def detect(view):
    import re
    # write-like tool call: App__<verb>... with a state-changing verb (ARE write_operation tools), never the reply tool itself
    write = re.compile(r"\b(?!AgentUserInterface__)[A-Z]\w*__(?:send|reply|forward|remove|delete|rm|rmdir|mv|move|mkdir|makedirs|download|create|add|update|set|save|order|edit|checkout|change|cancel|user_cancel|end)(?:_\w+)?\s*\(")
    code = view["pending"] or ""
    m = re.search(r"\bAgentUserInterface__send_message_to_user\s*\(", code)
    if not m:
        return False
    if write.search(code[:m.start()]):
        return False
    return not any(write.search(c["code"] or "") for c in view["cells"])
